/* Client-side table renderer. Fetches the JSON at ?url=… and renders it as an HTML table.
 * Replaces the former server-side table-view middleware — CAP now just returns plain JSON. */

const esc = s => String(s)
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;')

const baseUrlEl = document.getElementById('baseurl')
const pathInput = document.getElementById('path-input')
const countEl = document.getElementById('count')
const actionsEl = document.getElementById('actions')

// ── Request state (recomputed on every (re)load) ──
let target       // full absolute URL being requested
let dataPath     // target without query string
let prettyPath   // request path only (no origin), for display
let baseUrl      // origin + service prefix, shown on top
let serverOrigin // just the server origin, used as the base-URL link href
let editPath     // the editable portion: path + query (no origin)
let jsonLink     // plain-JSON link for the current target

function setTarget(url) {
  // Resolve against the current origin so relative input also works.
  target = url ? new URL(url, location.origin).href : ''
  dataPath = target.replace(/\?.*/, '').replace(/\/$/, '')
  try {
    const u = new URL(target)
    const { serviceBase, entityPath } = splitService(u.pathname.replace(/\/$/, ''))
    // Top row shows origin + protocol/service prefix; the editable field holds the entity part.
    serverOrigin = u.origin
    baseUrl = u.origin + serviceBase
    prettyPath = decode(u.pathname.replace(/\/$/, ''))
    editPath = decode(entityPath + (u.search || ''))
  } catch {
    serverOrigin = ''
    baseUrl = ''
    prettyPath = decode(dataPath)
    editPath = decode(target)
  }
  jsonLink = (() => {
    const [base, qs = ''] = target.split('?')
    const kept = qs.split('&').filter(Boolean)
    return kept.length ? `${base}?${kept.join('&')}` : base
  })()
}

// Split a request pathname into the service prefix (protocol + service path) and the
// remaining entity path. Recognises CAP protocol prefixes; otherwise falls back to
// treating everything but the last segment as the service base.
//   /odata/v4/books/Books(1)/author → { serviceBase: '/odata/v4/books', entityPath: '/Books(1)/author' }
//   /rest/books/Books               → { serviceBase: '/rest/books',     entityPath: '/Books' }
//   /books/Books                    → { serviceBase: '/books',          entityPath: '/Books' }
function splitService(path) {
  const protocols = [
    /^(\/odata\/v[0-9]+\/[^/]+)(\/.*)?$/,
    /^(\/odata\/[^/]+)(\/.*)?$/,
    /^(\/rest\/[^/]+)(\/.*)?$/,
  ]
  for (const re of protocols) {
    const m = path.match(re)
    if (m) return { serviceBase: m[1], entityPath: m[2] || '/' }
  }
  // Fallback: service = all but last segment, entity = last segment.
  const i = path.lastIndexOf('/')
  if (i > 0) return { serviceBase: path.slice(0, i), entityPath: path.slice(i) }
  return { serviceBase: '', entityPath: path }
}

// Percent-decode for display; fall back to the raw string if it's malformed.
function decode(s) {
  try { return decodeURIComponent(s) } catch { return s }
}

const LABELS_KEY = 'cds.table.labels' // 'human' (default) | 'raw'
let useHumanLabels = (() => {
  try { return localStorage.getItem(LABELS_KEY) !== 'raw' } catch { return true }
})()

// Turn a CSN element name into a human-friendly label.
// e.g. "createdAt" → "Created At", "book_ID" → "Book", "author_name" → "Author Name",
//      "ISBN" → "ISBN", "line-items" → "Line Items".
function humanize(name) {
  let s = String(name)
    .replace(/_ID$/, '')                         // drop generated FK suffix
    .replace(/[_-]+/g, ' ')                       // snake_case / kebab-case → spaces
    .replace(/([a-z\d])([A-Z])/g, '$1 $2')        // camelCase → words
    .replace(/([A-Z]+)([A-Z][a-z])/g, '$1 $2')    // ACRONYMFollowed → ACRONYM Followed
    .trim()
  if (!s) return String(name)
  return s.split(/\s+/).map(w =>
    /^[A-Z0-9]+$/.test(w) ? w                     // keep acronyms as-is (ID, ISBN, URL)
      : w.charAt(0).toUpperCase() + w.slice(1)
  ).join(' ')
}

const ICON_JSON = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M8 3H7a2 2 0 0 0-2 2v4a2 2 0 0 1-2 2 2 2 0 0 1 2 2v4a2 2 0 0 0 2 2h1"/><path d="M16 3h1a2 2 0 0 1 2 2v4a2 2 0 0 0 2 2 2 2 0 0 0-2 2v4a2 2 0 0 1-2 2h-1"/></svg>'
const ICON_LABELS = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M9 5H2v7l6.29 6.29c.94.94 2.48.94 3.42 0l3.58-3.58c.94-.94.94-2.48 0-3.42L9 5Z"/><path d="M6 9.01V9"/><path d="m15 5 6.3 6.3a2.4 2.4 0 0 1 0 3.4L17 19"/></svg>'

// Submit the edited URL. Absolute URL → use as-is; otherwise resolve against the base URL.
function submit() {
  const val = pathInput.value.trim()
  if (!val) return
  if (/^https?:\/\//i.test(val)) navigate(val)
  else navigate((baseUrl || '') + (val.startsWith('/') ? '' : '/') + val)
}

// Wire the editable path + GET button once (elements persist across renders).
pathInput.addEventListener('keydown', e => {
  if (e.key === 'Enter') { e.preventDefault(); submit() }
  else if (e.key === 'Escape') { pathInput.value = editPath; pathInput.blur() }
})
document.getElementById('get-btn').addEventListener('click', submit)

// Populates the header: base URL (top row), editable path, row count, and action chips.
function setHeader(count = null, withToggle = false) {
  // Server URL text (origin + service prefix) links to the server's base origin only.
  baseUrlEl.innerHTML = baseUrl
    ? `<a href="${esc(serverOrigin)}" target="_blank" rel="noopener" title="Open server (${esc(serverOrigin)})">${esc(baseUrl)}</a>`
    : ''
  pathInput.value = editPath
  countEl.innerHTML = count || ''
  const toggle = withToggle
    ? `<a class="chip" href="#" id="labels-toggle">${ICON_LABELS}${useHumanLabels ? 'Elements' : 'Labels'}</a>`
    : ''
  actionsEl.innerHTML =
    `${toggle}<a class="chip" href="${esc(jsonLink)}">${ICON_JSON}JSON</a>`
}

// Load a new URL: update the browser history (shareable + back button) and re-fetch.
function navigate(url) {
  const abs = new URL(url, location.origin).href
  const pageUrl = location.pathname + '?url=' + encodeURIComponent(abs)
  history.pushState({ url: abs }, '', pageUrl)
  run(abs)
}

window.addEventListener('popstate', () => {
  run(new URLSearchParams(location.search).get('url') || '')
})

run(new URLSearchParams(location.search).get('url') || '')

// Replaces the current #out node (whatever it currently is) with new markup.
function setOut(html) {
  document.getElementById('out').outerHTML = html
}

async function run(url) {
  setTarget(url)
  document.title = prettyPath || 'Table View'
  if (!target) {
    setHeader()
    setOut(`<div class="state error" id="out"><span class="big">Nothing to show</span>No <code>?url=</code> parameter given.</div>`)
    return
  }
  // Only fetch same-host URLs — the ?url= parameter is user-controlled and must not
  // be used to proxy requests to arbitrary hosts. Port is intentionally not checked so
  // local dev scenarios (e.g. table view on :4004 fetching a service on :3000) work.
  if (new URL(target).hostname !== location.hostname) {
    setHeader()
    setOut(`<div class="state error" id="out"><span class="big">Forbidden</span>Only same-host URLs are supported.</div>`)
    return
  }
  setHeader(null, false)
  setOut(`<div class="state" id="out"><span class="big">Loading…</span></div>`)
  let res, data
  try {
    res = await fetch(target, { headers: { accept: 'application/json' } })
    data = await res.json().catch(() => null)
  } catch (e) {
    setHeader()
    setOut(`<div class="state error" id="out"><span class="big">Request failed</span>${esc(e.message || '')}</div>`)
    return
  }

  const error = data?.error
  if (error || res.status >= 400) {
    const msg = error?.message ?? (data ? JSON.stringify(data) : res.statusText)
    setHeader()
    setOut(`<div class="state error" id="out"><span class="big"><span class="code">${res.status}</span>Error</span>${esc(msg)}</div>`)
    return
  }

  renderTable(data)
}

function renderTable(data) {
  const total = data?.['@odata.count']
  // REST service roots return { entities: [...] }; OData collections use { value: [...] }.
  const results = data?.value ?? data?.entities ?? data?.data ?? data
  const rawRows = Array.isArray(results) ? results : [results]
  const rows = rawRows.map(r => {
    const clean = {}
    for (const k in r) if (!k.startsWith('@')) clean[k] = r[k]
    return clean
  })

  if (!rows.length || rows.every(r => r == null)) {
    setHeader()
    setOut(`<div class="state" id="out"><span class="big">No data</span>This collection is empty.</div>`)
    return
  }

  // Union of columns across rows, preserving first-seen order.
  const rawCols = []
  const seen = new Set()
  for (const r of rows) for (const k in r) if (!seen.has(k)) { seen.add(k); rawCols.push(k) }

  const keyCol = rawCols.find(c => /^id$/i.test(c))
  const draftCol = rawCols.find(c => c === 'IsActiveEntity')
  // Without server-side CSN we heuristically classify columns by name/value.
  const keySet = new Set(keyCol ? [keyCol] : [])
  if (draftCol) keySet.add(draftCol)
  const isManaged = c => /^(createdAt|createdBy|modifiedAt|modifiedBy)$/.test(c)
  const isDraftCol = c => /^(IsActiveEntity|HasActiveEntity|HasDraftEntity|DraftAdministrativeData)$/.test(c)
  const isNumericCol = c => rows.some(r => typeof r[c] === 'number') &&
    rows.every(r => r[c] == null || typeof r[c] === 'number')

  // Column order: keys → business columns → managed (createdAt/By…) → draft-technical last.
  // Array.sort is stable, so columns within each group preserve their original order.
  function rank(c) {
    if (isDraftCol(c)) return 3
    if (keySet.has(c) && c !== draftCol) return 0
    if (isManaged(c)) return 2
    return 1
  }
  const cols = [...rawCols].sort((a, b) => rank(a) - rank(b))
  const numCols = new Set(cols.filter(isNumericCol))

  // Sort state: no column → original (ranked) order. 1 = ascending, -1 = descending.
  let sortCol = null, sortDir = 1

  const fmt = v => {
    if (v === null || v === undefined) return '<span class="null">null</span>'
    if (typeof v === 'boolean') return v ? '✓' : '✗'
    if (typeof v !== 'object') return esc(v)
    const json = esc(JSON.stringify(v))
    return `<span class="obj" title="${json}">${Array.isArray(v) ? `${v.length} items` : '{…}'}</span>`
  }

  const buildHead = () => cols.map(c => {
    const label = useHumanLabels ? humanize(c) : c
    const title = useHumanLabels ? c : humanize(c)
    const classes = []
    if (keySet.has(c)) classes.push('key')
    if (numCols.has(c)) classes.push('num')
    const sorted = c === sortCol ? ` aria-sort="${sortDir === 1 ? 'ascending' : 'descending'}"` : ''
    const arrow = c === sortCol ? `<span class="sort-ind">${sortDir === 1 ? '▲' : '▼'}</span>` : ''
    const cls = classes.length ? ` class="${classes.join(' ')}"` : ''
    return `<th${cls}${sorted} data-col="${esc(c)}" title="${esc(title)}"><span class="colname">${esc(label)}${arrow}</span></th>`
  }).join('')

  // Null/undefined always sort last; otherwise compare by type (numbers numerically,
  // everything else as locale-aware strings), then flip by the chosen direction.
  const compare = (a, b) => {
    const x = a[sortCol], y = b[sortCol]
    const xn = x === null || x === undefined, yn = y === null || y === undefined
    if (xn && yn) return 0
    if (xn) return 1
    if (yn) return -1
    let r
    if (typeof x === 'number' && typeof y === 'number') r = x - y
    else if (typeof x === 'boolean' && typeof y === 'boolean') r = (x === y) ? 0 : x ? 1 : -1
    else r = String(x).localeCompare(String(y), undefined, { numeric: true, sensitivity: 'base' })
    return r * sortDir
  }

  const render = () => {
    const sorted = sortCol ? [...rows].sort(compare) : rows
    const trs = sorted.map(r => {
      const tds = cols.map(c => {
        const classes = []
        if (numCols.has(c)) classes.push('num')
        if (keySet.has(c)) classes.push('key')
        const cls = classes.length ? ` class="${classes.join(' ')}"` : ''
        return `<td${cls}>${fmt(r[c])}</td>`
      }).join('')
      return `<tr>${tds}</tr>`
    }).join('\n')

    const count = `${rows.length}${total != null ? ` of ${total}` : ''} rows`
    setHeader(count, true)
    setOut(`<div class="scroll" id="out"><table>\n<thead><tr>${buildHead()}</tr></thead>\n<tbody>\n${trs}\n</tbody>\n</table></div>`)

    const toggle = document.getElementById('labels-toggle')
    if (toggle) toggle.addEventListener('click', e => {
      e.preventDefault()
      useHumanLabels = !useHumanLabels
      try { localStorage.setItem(LABELS_KEY, useHumanLabels ? 'human' : 'raw') } catch { /* ignore */ }
      render()
    })

    document.querySelectorAll('thead th[data-col]').forEach(th => {
      th.addEventListener('click', () => {
        const c = th.dataset.col
        if (sortCol === c) sortDir = -sortDir // toggle asc ⇄ desc
        else { sortCol = c; sortDir = 1 }
        render()
      })
    })
  }
  render()
}
